import React, { useState, useRef, useEffect, useCallback } from "react";
import { Plus, Mic, X, Check, Keyboard, ArrowUp, AudioLines } from "lucide-react";

/**
 * Stoic-style voice input.
 * Three states:
 *  - idle       : text bar with + / mic / voice-mode icon (ChatGPT style)
 *  - dictating  : mic is live, real audio-reactive waveform, X cancels, check confirms
 *  - voiceMode  : fullscreen orb conversation loop (listen -> think -> speak -> repeat)
 */

const VOID_BG = "#0b0b0d";
const BAR_BG = "#1c1c1f";
const CLAY = "#CC785C";
const PERIWINKLE = "#7C83DB";
const TEXT = "#EDEDED";
const SUBTEXT = "#8b8b90";

const LOGO_DATA_URI = "data:image/png;base64,";

export default function VoiceInput() {
  const [mode, setMode] = useState("idle"); // idle | dictating | voiceMode
  const [text, setText] = useState("");
  const [levels, setLevels] = useState(Array(28).fill(2));
  const [showTip, setShowTip] = useState(false);

  const recognitionRef = useRef(null);
  const audioCtxRef = useRef(null);
  const analyserRef = useRef(null);
  const streamRef = useRef(null);
  const rafRef = useRef(null);
  const finalTranscriptRef = useRef("");

  const SpeechRecognitionAPI =
    typeof window !== "undefined" &&
    (window.SpeechRecognition || window.webkitSpeechRecognition);

  // ---------- shared audio-level animation ----------
  const startLevelMeter = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      audioCtxRef.current = ctx;
      const source = ctx.createMediaStreamSource(stream);
      const analyser = ctx.createAnalyser();
      analyser.fftSize = 64;
      source.connect(analyser);
      analyserRef.current = analyser;
      const data = new Uint8Array(analyser.frequencyBinCount);

      const tick = () => {
        analyser.getByteFrequencyData(data);
        const bars = Array.from({ length: 28 }, (_, i) => {
          const v = data[i % data.length] || 0;
          return Math.max(2, Math.min(28, (v / 255) * 28));
        });
        setLevels(bars);
        rafRef.current = requestAnimationFrame(tick);
      };
      tick();
    } catch (e) {
      console.error("Mic access denied:", e);
    }
  }, []);

  const stopLevelMeter = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    if (streamRef.current) streamRef.current.getTracks().forEach((t) => t.stop());
    if (audioCtxRef.current) audioCtxRef.current.close();
    setLevels(Array(28).fill(2));
  }, []);

  // ---------- dictation ----------
  const beginDictation = async () => {
    setMode("dictating");
    setShowTip(true);
    setTimeout(() => setShowTip(false), 1800);
    finalTranscriptRef.current = text;
    await startLevelMeter();

    if (SpeechRecognitionAPI) {
      const rec = new SpeechRecognitionAPI();
      rec.continuous = true;
      rec.interimResults = true;
      rec.lang = "en-US";
      rec.onresult = (e) => {
        let interim = "";
        for (let i = e.resultIndex; i < e.results.length; i++) {
          const t = e.results[i][0].transcript;
          if (e.results[i].isFinal) finalTranscriptRef.current += t + " ";
          else interim += t;
        }
        setText((finalTranscriptRef.current + interim).trim());
      };
      rec.onerror = (e) => console.error("Speech recognition error:", e.error);
      rec.start();
      recognitionRef.current = rec;
    }
  };

  const cancelDictation = () => {
    recognitionRef.current?.stop();
    stopLevelMeter();
    setMode("idle");
  };

  const confirmDictation = () => {
    recognitionRef.current?.stop();
    stopLevelMeter();
    setText(finalTranscriptRef.current.trim());
    setMode("idle");
  };

  // ---------- voice mode ----------
  return (
    <div
      style={{
        minHeight: "100vh",
        background: VOID_BG,
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-end",
        fontFamily:
          "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
      }}
    >
      {mode === "voiceMode" ? (
        <VoiceModeOverlay
          onExit={() => setMode("idle")}
          onSwitchToText={() => setMode("idle")}
          startLevelMeter={startLevelMeter}
          stopLevelMeter={stopLevelMeter}
          SpeechRecognitionAPI={SpeechRecognitionAPI}
        />
      ) : (
        <div style={{ padding: "0 20px 32px", position: "relative" }}>
          {mode === "dictating" ? (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 12,
                background: BAR_BG,
                borderRadius: 28,
                padding: "10px 16px",
                position: "relative",
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 3,
                  flex: 1,
                  height: 28,
                  overflow: "hidden",
                }}
              >
                {levels.map((h, i) => (
                  <div
                    key={i}
                    style={{
                      width: 3,
                      height: h,
                      borderRadius: 2,
                      background: SUBTEXT,
                      transition: "height 60ms linear",
                    }}
                  />
                ))}
              </div>
              <button onClick={cancelDictation} style={iconBtnStyle}>
                <X size={18} color={TEXT} />
              </button>
              <button
                onClick={confirmDictation}
                style={{ ...iconBtnStyle, background: PERIWINKLE }}
                onMouseEnter={() => setShowTip(true)}
                onMouseLeave={() => setShowTip(false)}
              >
                <Check size={18} color={VOID_BG} />
              </button>

              {showTip && (
                <div
                  style={{
                    position: "absolute",
                    right: 8,
                    bottom: -34,
                    background: "#2a2a2e",
                    color: TEXT,
                    fontSize: 12,
                    padding: "5px 10px",
                    borderRadius: 6,
                    whiteSpace: "nowrap",
                    boxShadow: "0 2px 8px rgba(0,0,0,0.4)",
                  }}
                >
                  <b>Dictate</b>{" "}
                  <span style={{ color: SUBTEXT }}>Ctrl+Shift+D</span>
                </div>
              )}
            </div>
          ) : (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                background: BAR_BG,
                borderRadius: 28,
                padding: "8px 10px 8px 16px",
              }}
            >
              <button style={iconBtnStyle}>
                <Plus size={20} color={SUBTEXT} />
              </button>
              <input
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder="Ask anything"
                style={{
                  flex: 1,
                  background: "transparent",
                  border: "none",
                  outline: "none",
                  color: TEXT,
                  fontSize: 16,
                  padding: "8px 4px",
                }}
              />
              {text.trim() ? (
                <button
                  style={{ ...iconBtnStyle, background: CLAY }}
                  onClick={() => setText("")}
                >
                  <ArrowUp size={18} color={VOID_BG} />
                </button>
              ) : (
                <>
                  <button onClick={beginDictation} style={iconBtnStyle}>
                    <Mic size={20} color={SUBTEXT} />
                  </button>
                  <button
                    onClick={() => setMode("voiceMode")}
                    style={{ ...iconBtnStyle, background: TEXT }}
                  >
                    <AudioLines size={18} color={VOID_BG} />
                  </button>
                </>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ============ Fullscreen voice-mode conversation ============
function VoiceModeOverlay({ onExit, onSwitchToText, SpeechRecognitionAPI }) {
  const [status, setStatus] = useState("listening"); // listening | thinking | speaking
  const [lastLine, setLastLine] = useState("Listening…");
  const historyRef = useRef([]);
  const recognitionRef = useRef(null);
  const stoppedRef = useRef(false);

  const speak = (text) => {
    return new Promise((resolve) => {
      const utter = new SpeechSynthesisUtterance(text);
      utter.onstart = () => setStatus("speaking");
      utter.onend = () => resolve();
      utter.rate = 1;
      window.speechSynthesis.speak(utter);
    });
  };

  const askClaude = async (userText) => {
    historyRef.current.push({ role: "user", content: userText });
    setStatus("thinking");
    setLastLine("Thinking…");
    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 1000,
          messages: [
            {
              role: "user",
              content:
                "You are a warm, concise voice assistant. Reply in 1-3 short spoken sentences, no markdown. " +
                "Conversation so far: " +
                JSON.stringify(historyRef.current),
            },
          ],
        }),
      });
      const data = await response.json();
      const reply =
        data.content?.find((c) => c.type === "text")?.text ||
        "Sorry, I didn't catch that.";
      historyRef.current.push({ role: "assistant", content: reply });
      setLastLine(reply);
      await speak(reply);
    } catch (e) {
      console.error(e);
      setLastLine("Something went wrong reaching Claude.");
      await speak("Sorry, I ran into a problem.");
    }
    if (!stoppedRef.current) {
      setStatus("listening");
      setLastLine("Listening…");
    }
  };

  useEffect(() => {
    if (!SpeechRecognitionAPI) {
      setLastLine("Voice mode needs Chrome/Edge for microphone support.");
      return;
    }
    const rec = new SpeechRecognitionAPI();
    rec.continuous = true;
    rec.interimResults = false;
    rec.lang = "en-US";
    rec.onresult = (e) => {
      const t = e.results[e.results.length - 1][0].transcript.trim();
      if (t && status !== "thinking" && status !== "speaking") {
        askClaude(t);
      }
    };
    rec.onerror = (e) => console.error("Speech error:", e.error);
    rec.onend = () => {
      if (!stoppedRef.current) rec.start(); // keep listening loop alive
    };
    rec.start();
    recognitionRef.current = rec;

    return () => {
      stoppedRef.current = true;
      rec.stop();
      window.speechSynthesis.cancel();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const orbColor =
    status === "listening" ? PERIWINKLE : status === "thinking" ? "#9aa0e8" : CLAY;

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: VOID_BG,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "60px 24px 40px",
      }}
    >
      <div />
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 28 }}>
        <div
          style={{
            width: 200,
            height: 200,
            borderRadius: "50%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            background: `radial-gradient(circle, ${orbColor}40 0%, ${orbColor}15 55%, transparent 75%)`,
            boxShadow: `0 0 70px ${orbColor}66`,
            transition: "box-shadow 0.4s ease",
          }}
        >
          <img
            src={LOGO_DATA_URI}
            alt="Stoic"
            style={{
              width: 150,
              height: 150,
              borderRadius: "50%",
              filter: `drop-shadow(0 0 18px ${orbColor}aa)`,
              animation:
                status === "listening"
                  ? "stoicSpinSlow 6s linear infinite"
                  : status === "thinking"
                  ? "stoicSpinFast 1.1s linear infinite"
                  : "stoicSpinPulse 2.2s ease-in-out infinite",
            }}
          />
        </div>
        <p style={{ color: TEXT, fontSize: 15, maxWidth: 320, textAlign: "center", opacity: 0.85 }}>
          {lastLine}
        </p>
      </div>
      <div style={{ display: "flex", gap: 20 }}>
        <button onClick={onSwitchToText} style={{ ...roundBtn, background: BAR_BG }}>
          <Keyboard size={20} color={TEXT} />
        </button>
        <button onClick={onExit} style={{ ...roundBtn, background: "#3a1f1a" }}>
          <X size={20} color={TEXT} />
        </button>
      </div>

      <style>{`
        @keyframes stoicSpinSlow {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        @keyframes stoicSpinFast {
          from { transform: rotate(0deg) scale(1); }
          50% { transform: rotate(180deg) scale(1.06); }
          to { transform: rotate(360deg) scale(1); }
        }
        @keyframes stoicSpinPulse {
          0% { transform: rotate(0deg) scale(1); }
          50% { transform: rotate(180deg) scale(1.1); }
          100% { transform: rotate(360deg) scale(1); }
        }
      `}</style>
    </div>
  );
}

const iconBtnStyle = {
  width: 36,
  height: 36,
  borderRadius: "50%",
  border: "none",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  background: "transparent",
  cursor: "pointer",
  flexShrink: 0,
};

const roundBtn = {
  width: 52,
  height: 52,
  borderRadius: "50%",
  border: "none",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  cursor: "pointer",
};